// Validate weights: known criteria, numeric, non-negative. Unknown/negative/invalid rejected.
const CRITERIA = ['price','quality','reviews','delivery','warranty','vendor_reliability','payment_terms','budget_compliance','source_quality','specification_completeness'];
const b = $input.first().json;
const weights = b.weights ?? {};
const errors = [];
for (const [k, w] of Object.entries(weights)) {
  if (!CRITERIA.includes(k)) errors.push('unknown criterion: ' + k);
  else if (typeof w !== 'number' || Number.isNaN(w)) errors.push('non-numeric weight: ' + k);
  else if (w < 0) errors.push('negative weight: ' + k);
}
if (errors.length) throw new Error('invalid weights: ' + errors.join('; '));
return [{ json: { components: b.components ?? {}, weights, product_id: b.product_id ?? null } }];

// Deterministic weighted score with renormalization over available criteria only.
const { components, weights } = $input.first().json;
const used = [], missing = [], breakdown = {};
let num = 0, den = 0;
for (const c of ['price','quality','reviews','delivery','warranty','vendor_reliability','payment_terms','budget_compliance','source_quality','specification_completeness']) {
  const w = weights[c] ?? 0;
  const v = components[c];
  if (w === 0) continue;
  if (typeof v === 'number' && !Number.isNaN(v) && v >= 0 && v <= 1) {
    used.push(c); num += w * v; den += w;
    breakdown[c] = { score: v, weight: w, contribution: w * v };
  } else { missing.push(c); breakdown[c] = { score: null, weight: w, contribution: 0 }; }
}
const _inp = $input.first().json;
return [{ json: { product_id: _inp.product_id ?? null, overall_score: den > 0 ? num / den : null, criteria_used: used, criteria_missing: missing, effective_weight_total: den, breakdown } }];
